ALLOWED_PROFILE_FIELDS = {"display_name", "bio"}
def update_profile(existing, submitted):
    updated = existing.copy()
    for key in ALLOWED_PROFILE_FIELDS:
        if key in submitted:
            updated[key] = submitted[key]
    return updated

