SENSITIVE_KEYS = {"password", "password_hash", "api_key", "session_token"}
def find_sensitive_fields(payload, path=""):
    findings = []
    if isinstance(payload, dict):
        for key, value in payload.items():
            current = f"{path}.{key}" if path else key
            if key.lower() in SENSITIVE_KEYS:
                findings.append(current)
            findings.extend(find_sensitive_fields(value, current))
    elif isinstance(payload, list):
        for index, value in enumerate(payload):
            findings.extend(find_sensitive_fields(value, f"{path}[{index}]"))
    return findings

