import ipaddress
def is_local_lab_target(host):
    try:
        address = ipaddress.ip_address(host)
        return address.is_loopback
    except ValueError:
        return host.lower() == "localhost"

for host in ["127.0.0.1", "::1", "localhost", "example.com"]:
    print(host, is_local_lab_target(host))
